Here is the commit message:
bnxt_en: Fix handling FRAG_ERR when NVM_INSTALL_UPDATE cmd
 fails

If FW returns FRAG_ERR in response error code, driver is resending the
command only when HWRM command returns success. Fix the code to resend
NVM_INSTALL_UPDATE command with DEFRAG install flags, if FW returns
FRAG_ERR in its response error code.

Fixes: cb4d1d626145 ("bnxt_en: Retry failed NVM_INSTALL_UPDATE with defragmentation flag enabled.")
Signed-off-by: Vasundhara Volam <vasundhara-v.volam@broadcom.com>
Signed-off-by: Michael Chan <michael.chan@broadcom.com>
Signed-off-by: David S. Miller <davem@davemloft.net>

Here is the root cause:
The bug was caused by the driver only resending the `NVM_INSTALL_UPDATE` command when the HWRM command returned success, without properly handling the case where the firmware returned a `FRAG_ERR` error code. This oversight meant that fragmentation errors were not addressed, potentially leading to failed updates without retrying the command with the necessary defragmentation flags.

Here is the patch:

 static int bnxt_flash_package_from_file(struct net_device *dev,
 					char *filename, u32 install_type)
 {
 	struct bnxt *bp = netdev_priv(dev);
 	struct hwrm_nvm_install_update_output *resp = bp->hwrm_cmd_resp_addr;
 	struct hwrm_nvm_install_update_input install = {0};
 	const struct firmware *fw;
 	int rc, hwrm_err = 0;
 	u32 item_len;
 	u16 index;

 	bnxt_hwrm_fw_set_time(bp);

 	if (bnxt_find_nvram_item(dev, BNX_DIR_TYPE_UPDATE,
 				 BNX_DIR_ORDINAL_FIRST, BNX_DIR_EXT_NONE,
 				 &index, &item_len, NULL) != 0) {
 		netdev_err(dev, "PKG update area not created in nvram\n");
 		return -ENOBUFS;
 	}

 	rc = request_firmware(&fw, filename, &dev->dev);
 	if (rc != 0) {
 		netdev_err(dev, "PKG error %d requesting file: %s\n",
 			   rc, filename);
 		return rc;
 	}

 	if (fw->size > item_len) {
 		netdev_err(dev, "PKG insufficient update area in nvram: %lu",
 			   (unsigned long)fw->size);
 		rc = -EFBIG;
 	} else {
 		dma_addr_t dma_handle;
 		u8 *kmem;
 		struct hwrm_nvm_modify_input modify = {0};

 		bnxt_hwrm_cmd_hdr_init(bp, &modify, HWRM_NVM_MODIFY, -1, -1);

 		modify.dir_idx = cpu_to_le16(index);
 		modify.len = cpu_to_le32(fw->size);

 		kmem = dma_alloc_coherent(&bp->pdev->dev, fw->size,
 					  &dma_handle, GFP_KERNEL);
 		if (!kmem) {
 			netdev_err(dev,
 				   "dma_alloc_coherent failure, length = %u\n",
 				   (unsigned int)fw->size);
 			rc = -ENOMEM;
 		} else {
 			memcpy(kmem, fw->data, fw->size);
 			modify.host_src_addr = cpu_to_le64(dma_handle);

 			hwrm_err = hwrm_send_message(bp, &modify,
 						     sizeof(modify),
 						     FLASH_PACKAGE_TIMEOUT);
 			dma_free_coherent(&bp->pdev->dev, fw->size, kmem,
 					  dma_handle);
 		}
 	}
 	release_firmware(fw);
 	if (rc || hwrm_err)
 		goto err_exit;

 	if ((install_type & 0xffff) == 0)
 		install_type >>= 16;
 	bnxt_hwrm_cmd_hdr_init(bp, &install, HWRM_NVM_INSTALL_UPDATE, -1, -1);
 	install.install_type = cpu_to_le32(install_type);

 	mutex_lock(&bp->hwrm_cmd_lock);
 	hwrm_err = _hwrm_send_message(bp, &install, sizeof(install),
 				      INSTALL_PACKAGE_TIMEOUT);
-	if (hwrm_err)
-		goto flash_pkg_exit;
-
-	if (resp->error_code) {
+	if (hwrm_err) {
 		u8 error_code = ((struct hwrm_err_output *)resp)->cmd_err;

-		if (error_code == NVM_INSTALL_UPDATE_CMD_ERR_CODE_FRAG_ERR) {
+		if (resp->error_code && error_code ==
+		    NVM_INSTALL_UPDATE_CMD_ERR_CODE_FRAG_ERR) {
 			install.flags |= cpu_to_le16(
 			       NVM_INSTALL_UPDATE_REQ_FLAGS_ALLOWED_TO_DEFRAG);
 			hwrm_err = _hwrm_send_message(bp, &install,
 						      sizeof(install),
 						      INSTALL_PACKAGE_TIMEOUT);
-			if (hwrm_err)
-				goto flash_pkg_exit;
 		}
+		if (hwrm_err)
+			goto flash_pkg_exit;
 	}

 	if (resp->result) {
 		netdev_err(dev, "PKG install error = %d, problem_item = %d\n",
 			   (s8)resp->result, (int)resp->problem_item);
 		rc = -ENOPKG;
 	}
 flash_pkg_exit:
 	mutex_unlock(&bp->hwrm_cmd_lock);
 err_exit:
 	if (hwrm_err == HWRM_ERR_CODE_RESOURCE_ACCESS_DENIED) {
 		netdev_info(dev,
 			    "PF does not have admin privileges to flash the device\n");
 		rc = -EACCES;
 	} else if (hwrm_err) {
 		rc = -EOPNOTSUPP;
 	}
 	return rc;
 }



